def dump_dxf(path):
    print(f'================ {path} ================')
    lines = [l.strip() for l in open(path).readlines()]
    pairs = [(lines[i], lines[i+1]) for i in range(0, len(lines)-1, 2)]
    in_ent = False
    cur = None
    ents = []
    for code, val in pairs:
        if code == '0' and val == 'SECTION':
            cur = None
        elif code == '2' and val == 'ENTITIES':
            in_ent = True
        elif code == '0' and val == 'ENDSEC' and in_ent:
            if cur: ents.append(cur)
            in_ent = False
        elif in_ent:
            if code == '0':
                if cur: ents.append(cur)
                cur = {'type': val}
            elif cur is not None:
                if code == '8': cur['layer'] = val
                elif code == '1': cur['text'] = val
                elif code in ('10', '11'): cur.setdefault('xs', []).append((code, float(val)))
                elif code in ('20', '21'): cur.setdefault('ys', []).append((code, float(val)))
                elif code == '40': cur['r'] = float(val)
    for i, e in enumerate(ents):
        if e.get('layer') in ('BORINGS', 'TREES', 'NOTES', 'TITLE') or i >= 85:
            print(i, e)

