def get_db_amp(size, cir, rho, lf, depth=30, amb=25):
    # Next higher cir in [1,2,3,4,6]
    c_tab = min([c for c in [1,2,3,4,6] if c >= cir])
    r_tab = min([r for r in [60,90,120,150] if r >= rho])
    d_tab = min([d for d in [30,48,72,120,180] if d >= depth])
    for r in db_rows:
        if str(r[0]) == str(size) and r[1] == c_tab and r[2] == r_tab and r[3] == lf:
            return r[6] * depth_rows[str(size)][d_tab] * amb_rows[str(size)][amb]

